private static char decodeUTF8(int i, ByteBuffer bb) {
    char c;
    int byte1 = bb.get(i);
    if (byte1 < 128) {
        c = (char)byte1;
    } else {
        int byte2 = bb.get(i + 1);
        if (byte2 < 128) {
            throw new IllegalArgumentException("Invalid UTF-8 byte sequence");
        }
        int byte3 = bb.get(i + 2);
        if (byte3 < 128) {
            throw new IllegalArgumentException("Invalid UTF-8 byte sequence");
        }
        c = (char)((byte1 << 12) | (byte2 << 6) | byte3);
    }
    return c;
}

