public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Initialize the graph with vertices and edges
    int numVertices = resultMap.size();
    int numEdges = (numVertices * (numVertices - 1)) / 2;
    target.addVertices(numVertices);
    target.addEdges(numEdges);

    // Add edges to the graph
    int numEdge = 0;
    for (V vertex1 : resultMap.keySet()) {
        for (V vertex2 : resultMap.keySet()) {
            if (vertex1 != vertex2) {
                target.addEdge(vertex1, vertex2, numEdge);
                numEdge++;
            }
        }
    }

    // Update the adjacency map of each vertex
    for (V vertex : resultMap.keySet()) {
        Set<E> edges = target.getEdges(vertex);
        for (E edge : edges) {
            V neighbor = target.getOtherEnd(vertex, edge);
            resultMap.get(vertex).getAdjacencyMap().put(neighbor, edge);
        }
    }
}
