public class GenericTypeResolver{
    private Map<Class<?>,Reference<Map<TypeVariable<?>,Type>>> typeVariableCache;
    private boolean cacheEnabled = true;

    /**
     * Returns the raw class representing the type argument for the type using type variable information from the subtype.
     * If no arguments can be resolved, {@code unknown.class} is returned.
     */
    public Class<?> resolveGenericType(Class<?> genericType, Class<?> targetType){
        //If cache is enabled and the type variable cache for the target type is present, return the type from the cache
        if(cacheEnabled && typeVariableCache.containsKey(targetType)){
            Map<TypeVariable<?>,Type> typeVariableMap = typeVariableCache.get(targetType);
            if(typeVariableMap.containsKey(genericType)){
                return typeVariableMap.get(genericType);
            }
        }
        //If the type variable cache for the target type is not present, or if the type is not present in the cache, resolve the type from the subtype
        Class<?> resolvedType = resolveRawType(genericType, targetType);
        //If the resolved type is not null, store it in the cache and return it
        if(resolvedType != null){
            if(!typeVariableCache.containsKey(targetType)){
                typeVariableCache.put(targetType, new Reference<Map<TypeVariable<?>,Type>>(new HashMap<>()));
            }
            Map<TypeVariable<?>,Type> typeVariableMap = typeVariableCache.get(targetType);
            typeVariableMap.put(genericType, resolvedType);
            return resolvedType;
        }
        //If the resolved type is null, return unknown.class
        return unknown.class;
    }

    /**
     * Returns the raw class representing the type using type variable information from the subtype.
     */
    public Class<?> resolveRawType(Type type, Class<?> targetType){
        if(targetType == type){
            return targetType;
        }
        if(type instanceof Class){
            return resolveRawClass((Class<?>) type, targetType);
        }
        if(type instanceof TypeVariable){
            return resolveRawClass((TypeVariable<?>) type, targetType);
        }
        //If the type is not a raw class, return null
        return null;
    }

    /**
     * Disables the cache for resolving generic types.
     */
    public void disableCache(){
        cacheEnabled = false;
    }

    /**
     * Enables the cache for resolving generic types.
     */
    public void enableCache(){
        cacheEnabled = true;
    }

    /**
     * Builds a type variable map for the given target class.
     */
    private void buildTypeVariableMap(Class<?> targetClass){
        TypeVariable<?>[] typeVariables = targetClass.getTypeParameters();
        Map<TypeVariable<?>,Type> typeVariableMap = new HashMap<>();
        for(TypeVariable<?> typeVariable: typeVariables){
            Type[] bounds = typeVariable.getBounds();
            if(bounds.length > 0){
                Type boundType = bounds[0];
                if(boundType instanceof TypeVariable){
                    typeVariableMap.put(typeVariable, boundType);
                }else{
                    typeVariableMap.put(typeVariable, boundType.getClass());
                }
            }
        }
        typeVariableCache.put(targetClass, new Reference<Map<TypeVariable<?>,Type>>(typeVariableMap));
    }

    /**
     * Resolves the boundaries of a wildcard type or an annotation type to the target class.
     */
    public Type resolveBound(Type type, Class<?> targetClass){
        if(type instanceof WildcardType){
            return resolveWildcardType((WildcardType) type, targetClass);
        }else if(type instanceof AnnotationType){
            return resolveAnnotationType((AnnotationType) type, targetClass);
        }
        return null;
    }

    /**
     * Resolves a wildcard type to the target class.
     */
    private Type resolveWildcardType(WildcardType wildcardType, Class<?> targetClass){
        Type[] upperBounds = wildcardType.getUpperBounds();
        Type[] lowerBounds = wildcardType.getLowerBounds();
        if(upperBounds.length > 0){
            return resolveBound(upperBounds[0], targetClass);
        }else if(lowerBounds.length > 0){
            return resolveBound(lowerBounds[0], targetClass);
        }
        return null;
    }

    /**
     * Resolves an annotation type to the target class.
     */
    private Type resolveAnnotationType(AnnotationType annotationType, Class<?> targetClass){
        Type[] typeBounds = annotationType.getComponentType();
        if(typeBounds.length > 0){
            return resolveBound(typeBounds[0], targetClass);
        }
        return null;
    }
}

