public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = Files.newBufferedReader(file.toPath())) {
        String line = reader.readLine();
        while (line != null) {
            String[] splitLine = line.split(",");
            ProfileAnalyzeTimeRange range = timeRanges.stream().filter(t -> t.getStartMillis() <= Long.parseLong(splitLine[0]) && t.getEndMillis() >= Long.parseLong(splitLine[0])).findFirst().orElseThrow(() -> new IOException("No time range found for timestamp"));
            snapshots.add(new ThreadSnapshot(Long.parseLong(splitLine[0]), Long.parseLong(splitLine[1]), Long.parseLong(splitLine[2]), range));
            line = reader.readLine();
        }
    } catch (IOException e) {
        throw new IOException("Error while reading from file", e);
    }
    return snapshots;
}
